from enum import Enum
from typing import Dict, Type, TypeVar, Generic
from threading import Lock

from app.client.review_analytics_client import ReviewAnalyticsServiceClient
from app.client.review_consumer_client import ReviewConsumerServiceClient
from app.client.code_probe_client import CodeProbeServiceClient
from app.client.pr_event_audit_client import PrEventAuditServiceClient
from app.core.settings import Settings
from app.client.base import BaseServiceClient
from app.client.tenant_client import TenantServiceClient
from app.client.review_crud_client import ReviewCRUDServiceClient
from app.client.webhook_client import WebhookServiceClient

T = TypeVar('T', bound=BaseServiceClient)


class ServiceType(Enum):
    TENANT = "tenant"
    REVIEW_CRUD = "review_crud"
    WEBHOOK = "webhook"
    REVIEW_CONSUMER = "review_consumer"
    REVIEW_ANALYTICS = "review_analytics"
    CODE_PROBE = "code_probe"
    PR_EVENT_AUDIT = "pr_event_audit"


class ServiceClientFactory:
    """Singleton factory for service clients"""
    _instance = None
    _lock = Lock()
    _settings: Settings = None

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if not self._settings:
            self._settings = Settings()
            self._initialize_clients()

    def _initialize_clients(self):
        """Initialize all clients lazily"""
        # Map service types to their client classes and settings
        self._client_mapping = {
            ServiceType.TENANT: (TenantServiceClient, self._settings.tenant_service),
            ServiceType.REVIEW_CRUD: (ReviewCRUDServiceClient, self._settings.review_crud_service),
            ServiceType.WEBHOOK: (WebhookServiceClient, self._settings.webhook_service),
            ServiceType.REVIEW_CONSUMER: (ReviewConsumerServiceClient, self._settings.review_consumer_service),
            ServiceType.REVIEW_ANALYTICS: (ReviewAnalyticsServiceClient, self._settings.review_analytics_service),
            ServiceType.CODE_PROBE: (CodeProbeServiceClient, self._settings.code_probe_service),
            ServiceType.PR_EVENT_AUDIT: (PrEventAuditServiceClient, self._settings.pr_event_audit_service)
        }

    def get_client(self, service_type: ServiceType) -> BaseServiceClient:
        """Get or create a service client"""
        client_class, settings = self._client_mapping[service_type]
        return client_class(settings)

    # Type-safe convenience methods
    def get_tenant_client(self) -> TenantServiceClient:
        return self.get_client(ServiceType.TENANT)
    def get_review_crud_client(self) -> ReviewCRUDServiceClient:
        return self.get_client(ServiceType.REVIEW_CRUD)
    def get_webhook_client(self) -> WebhookServiceClient:
        return self.get_client(ServiceType.WEBHOOK)
    def get_review_consumer_client(self) -> ReviewConsumerServiceClient:
        return self.get_client(ServiceType.REVIEW_CONSUMER)
    def get_review_analytics_client(self) -> ReviewAnalyticsServiceClient:
        return self.get_client(ServiceType.REVIEW_ANALYTICS)
    def get_code_probe_client(self) -> CodeProbeServiceClient:
        return self.get_client(ServiceType.CODE_PROBE)
    def get_pr_event_audit_client(self) -> PrEventAuditServiceClient:
        return self.get_client(ServiceType.PR_EVENT_AUDIT)

# Create global factory instance
factory = ServiceClientFactory()

