"""Tests for QuickPull audit event proxy route."""

import pytest
from unittest.mock import AsyncMock, MagicMock
from fastapi.testclient import TestClient

from main import app
from app.api.dep.client_deps import get_pr_event_audit_client
from app.api.middleware.auth import _base_require_auth
from tests.test_routes.conftest import TENANT_ID, USER_ID, _make_result


VALID_PAYLOAD = {
    "ide_type": "VSCode",
    "ide_version": "1.90.0",
    "action": "Resolved",
    "event_metadata": {
        "repo": "org/my-repo",
        "branch": "feature/test",
        "pr_number": "42",
        "file_name": "src/main.py",
        "commenters": ["user1", "user2"],
    },
}

MINIMAL_PAYLOAD = {
    "ide_type": "Cursor",
    "ide_version": "0.45.0",
    "action": "Fix with Agent",
}

CREATED_RESPONSE = {
    "id": "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee",
    "ide_type": "VSCode",
    "ide_version": "1.90.0",
    "action": "Resolved",
    "event_metadata": {"repo": "org/my-repo"},
    "created_at": "2026-05-18T00:00:00Z",
}


@pytest.fixture
def mock_pr_event_audit_client():
    return MagicMock()


@pytest.fixture
def client(mock_pr_event_audit_client):
    app.dependency_overrides[get_pr_event_audit_client] = lambda: mock_pr_event_audit_client
    yield TestClient(app, raise_server_exceptions=False)


class TestCreateQuickPullAudit:
    """Tests for POST /api/quick-pull-audit"""

    def test_success_with_full_payload(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            return_value=_make_result(data=CREATED_RESPONSE, status_code=201)
        )
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 201
        data = resp.json()
        assert data["ide_type"] == "VSCode"
        assert data["action"] == "Resolved"
        assert data["id"] == "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee"

    def test_success_without_metadata(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            return_value=_make_result(
                data={"id": "test-id", "ide_type": "Cursor", "ide_version": "0.45.0", "action": "Fix with Agent"},
                status_code=201,
            )
        )
        resp = client.post("/api/quick-pull-audit", json=MINIMAL_PAYLOAD)
        assert resp.status_code == 201
        assert resp.json()["ide_type"] == "Cursor"

    def test_missing_ide_type(self, client, mock_pr_event_audit_client):
        resp = client.post("/api/quick-pull-audit", json={"ide_version": "1.0", "action": "Resolved"})
        assert resp.status_code == 422

    def test_missing_ide_version(self, client, mock_pr_event_audit_client):
        resp = client.post("/api/quick-pull-audit", json={"ide_type": "VSCode", "action": "Resolved"})
        assert resp.status_code == 422

    def test_missing_action(self, client, mock_pr_event_audit_client):
        resp = client.post("/api/quick-pull-audit", json={"ide_type": "VSCode", "ide_version": "1.0"})
        assert resp.status_code == 422

    def test_empty_body(self, client, mock_pr_event_audit_client):
        resp = client.post("/api/quick-pull-audit", json={})
        assert resp.status_code == 422

    def test_downstream_failure(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            side_effect=Exception("connection refused")
        )
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 500

    def test_downstream_non_success(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            return_value=_make_result(data=None, status_code=502, error="bad gateway", is_success=False)
        )
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 502

    def test_downstream_timeout(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            return_value=_make_result(data=None, status_code=504, error="gateway timeout", is_success=False)
        )
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 504

    def test_downstream_null_response(self, client, mock_pr_event_audit_client):
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(return_value=None)
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 502

    def test_auth_header_injected(self, client, mock_pr_event_audit_client):
        """Verify the client method is called (which internally adds X-Service-Token via _prepare_headers)."""
        mock_pr_event_audit_client.create_quick_pull_audit = AsyncMock(
            return_value=_make_result(data=CREATED_RESPONSE, status_code=201)
        )
        resp = client.post("/api/quick-pull-audit", json=VALID_PAYLOAD)
        assert resp.status_code == 201
        mock_pr_event_audit_client.create_quick_pull_audit.assert_called_once()
